head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > checkboxLabel]<br/>inputType='checkbox' 인 Column 에 표시할 라벨 텍스트를 설정합니다.",
    "validation" : [
        "문자열 설정 시, Cell 의 체크박스 옆에 표시할 라벨 텍스트를 설정합니다.",
        "문자열 설정 시, 설정한 라벨 텍스트는 모든 Row 에 동일하게 적용됩니다.",
        "Body Column 의 escape=false 이면 라벨 텍스트에 이스케이프 처리를 하지 않습니다.",
        "Header Column 은 escape 속성값이 적용되지 않아 항상 특수문자를 이스케이프 처리합니다.",
        "라벨 텍스트 영역 클릭 시 체크박스가 선택/해제 됩니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_checkboxLabel.setSelectedIndex(1);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// XML 속성값 인코딩 (특수문자 라벨을 dynamicCreate 마크업 속성으로 넘기기 위함)
scwin.encodeAttr = function (str) {
    return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}



// comp 생성
//  - checkboxLabel 은 Header(column3) 와 Body(chk) 의 checkbox Column 양쪽에 고정 적용
//  - escape 는 Body Column(chk) 에만 설정 (Header 이스케이프 처리 비교용 전제 조건)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] checkboxLabel 은 Header 와 Body 의 chk Column 에 함께 적용, escape 는 Body Column 에만 적용\n[절차] Header 와 Body 의 라벨 텍스트를 직접 클릭\n[확인] 결과창의 라벨 textContent / innerHTML 과 클릭 후 체크 상태"', '', 'label1');

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다, gdl_boolean 은 getText() 로 '' / 'true' / 'false' 판단)
    let cCheckboxLabel = con_checkboxLabel.getValue();
    let cEscape = con_escape.getText();

    let attrCheckboxLabel = (cCheckboxLabel === '') ? '' : ' checkboxLabel="' + scwin.encodeAttr(cCheckboxLabel) + '"';
    let attrEscape = (cEscape === '') ? '' : ' escape="' + cEscape + '"';

    // dataList 생성
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="product" name="product" dataType="text"></w2:column>';
    strDlt += '<w2:column id="price" name="price" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "product" : "노트북", "price" : "1,250,000", "chk" : "0" },
        { "product" : "모니터", "price" : "320,000", "chk" : "1" },
        { "product" : "키보드", "price" : "89,000", "chk" : "0" },
        { "product" : "마우스", "price" : "45,000", "chk" : "1" }
    ], false);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:460px;height:170px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column1" value="상품명"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column2" value="가격"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="checkbox" id="column3" value=""' + attrCheckboxLabel + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="product" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="price" value=""></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="checkbox" id="chk" value=""' + attrCheckboxLabel + attrEscape + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 라벨 클릭 감지 (Header 를 다시 그려도 유지되도록 grid render 에서 capture 단계로 위임 처리)
    target1.render.addEventListener("click", scwin.onLabelClick, true);

    // validation 1 ~ 4 : 재생성 직후 Header / Body 라벨 출력
    setTimeout(function () {
        scwin.printLabelInfo();
    }, 100);
}



// Header chk Column 의 td 요소
scwin.getHeaderTd = function () {
    return document.querySelector("#" + target1.id + "_column3");
}



// 라벨 요소의 textContent / innerHTML 문자열 (escape 여부 비교용)
scwin.getLabelStr = function (label) {
    if (!label) {
        return "라벨 없음";
    }
    return "textContent='" + label.textContent + "', innerHTML='" + label.innerHTML + "'";
}



// validation 1 ~ 4 : Header / Body 의 라벨 텍스트 출력
scwin.printLabelInfo = function () {
    let headerTd = scwin.getHeaderTd();
    let headerLabel = headerTd ? headerTd.querySelector("label") : null;
    wf_body_bottom.getObj("scwin").setReturnValue("Header 라벨 : " + scwin.getLabelStr(headerLabel));

    let arr = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        let td = document.querySelector("td[id*='" + target1.id + "_cell_" + i + "_2']");
        let bodyLabel = td ? td.querySelector("label") : null;
        arr.push(i + "행 " + scwin.getLabelStr(bodyLabel));
    }
    wf_body_bottom.getObj("scwin").setReturnValue("Body 라벨 : " + arr.join(" / "));
}



// 행별 chk 값과 Header 체크 상태 문자열
scwin.getCheckInfo = function () {
    let arr = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        arr.push(i + "행=" + dlt_bind.getCellData(i, "chk"));
    }
    let headerTd = scwin.getHeaderTd();
    let hChk = headerTd ? headerTd.querySelector("input[type='checkbox']") : null;
    let strHeader = hChk ? "checked=" + hChk.checked + ", indeterminate=" + hChk.indeterminate : "체크박스 없음";
    return "Header 체크 상태 : " + strHeader + " / chk 값 : " + arr.join(", ");
}



// validation 5 : 라벨 텍스트 클릭 후 체크 상태 출력
scwin.onLabelClick = function (e) {
    let label = e.target.closest ? e.target.closest("label") : null;
    if (!label) {
        return;
    }
    let headerTd = scwin.getHeaderTd();
    let strTarget = (headerTd && headerTd.contains(label)) ? "Header 라벨 클릭" : "Body " + label.htmlFor.split("_").pop() + "행 라벨 클릭";
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue(strTarget + " -> " + scwin.getCheckInfo());
    }, 50);
}
